import { BehaviorSubject } from 'rxjs';

// Initial state: logged out
private authSubject = new BehaviorSubject<boolean>(false);
auth$ = this.authSubject.asObservable();

login() {
  this.authSubject.next(true);
}
logout() {
  this.authSubject.next(false);
}

private notifSubject = new ReplaySubject<string>(5);
notifications$ = this.notifSubject.asObservable();

addNotification(msg: string) {
  this.notifSubject.next(msg);
}
// New subscribers get the last 5 messages
